CREATE POLICY onedrive_document_authorization ON public.documenti AS RESTRICTIVE FOR ALL TO authenticated USING(onedrive_item_id IS NULL OR EXISTS(SELECT 1 FROM public.onedrive_access a WHERE a.user_id=auth.uid() AND a.user_id=documenti.user_id)) WITH CHECK(onedrive_item_id IS NULL OR EXISTS(SELECT 1 FROM public.onedrive_access a WHERE a.user_id=auth.uid() AND a.user_id=documenti.user_id));